def parse_int_list(s):
    """Parse a comma-separated string of integers into a list.

    Tolerates None, empty/whitespace-only input, and skips tokens that
    are not valid integers. Valid inputs behave exactly as before.
    """
    if s is None or not s.strip():
        return []
    result = []
    for token in s.split(","):
        token = token.strip()
        try:
            result.append(int(token))
        except ValueError:
            continue
    return result
